-- 📚 꼭집 주거 사전 — 영구임대 가군·나군 · 2026
-- 재계산 SQL(관리 API에서 그대로 실행 · 읽기만). 범위: 공고일 2026년 · 유형은 housing_type_map 표준값.
-- 확인 2026-10-29 · 2초 상한에서 멈춤(statement timeout) — 런칭 뒤 실행 · 결과: (비움 — 2026-10-29 4차에서 키를 더함 · 아래 10-13 결과는 그때 키만)
-- 확인 2026-10-13 · 실행 3.1초 · 결과:
-- {"anns": 29, "by_std": {"영구임대": 29}, "가군나군": 2, "가군나군_ex": ["2015122300020680", "2015122300020233"], "가군수급자": 13, "가군수급자_ex": ["2015122300020874", "2015122300020868", "2015122300020866"]}
with a as(select distinct on(x.announcement_id)x.announcement_id,x.supply_org org,coalesce(m.std_type,x.housing_type)std,extract(year from coalesce(x.announcement_date,x.created_at::date))::int yr from announcements x left join housing_type_map m on m.source_table='announcements' and m.source=x.source and m.housing_type=x.housing_type order by x.announcement_id,(x.source='LH')desc,x.created_at desc),y as(select p.announcement_id,regexp_replace(p.content_raw,'\s+',' ','g')t,coalesce(r.class_name,c.class_name)cls,a.org,a.std from announcement_policies p join a using(announcement_id) left join policy_row_classes r on r.policy_id=p.id and r.axis='standard' left join policy_category_classes c on c.category=p.category and c.axis='standard' where a.yr=2026),h as(select h.announcement_id,case when h.supply_target~'가군' and h.supply_target~'나군' then '혼합' when h.supply_target~'가군' then '가군' else '나군' end g,coalesce(nullif(btrim(h.sido_nm),''),'(시도 없음)') sido,h.area_sqm,h.monthly_rent,round(h.monthly_rent::numeric/h.area_sqm) v from housing_units h join a using(announcement_id) where a.yr=2026 and a.std='영구임대' and h.monthly_rent>0 and h.area_sqm>0 and h.supply_target~'[가나]군')select json_build_object('anns',(select count(distinct announcement_id) from y where std='영구임대'),'by_std',(select json_object_agg(std,n) from(select std,count(distinct announcement_id)n from y where std='영구임대' group by 1)q),'가군나군',(select count(distinct announcement_id) from y where std='영구임대' and t~'가\s*군[^.]{0,80}나\s*군'),'가군나군_ex',(select json_agg(i) from(select distinct announcement_id i from y where std='영구임대' and t~'가\s*군[^.]{0,80}나\s*군' order by 1 desc limit 3)q),'가군수급자',(select count(distinct announcement_id) from y where std='영구임대' and t~'가\s*군[^.]{0,60}(수급자|차상위)'),'가군수급자_ex',(select json_agg(i) from(select distinct announcement_id i from y where std='영구임대' and t~'가\s*군[^.]{0,60}(수급자|차상위)' order by 1 desc limit 3)q),'월세_by_g',(select json_object_agg(g,o) from(select g,json_build_object('rows',count(*),'anns',count(distinct announcement_id),'m2_min',min(v),'m2_med',round(percentile_cont(0.5)within group(order by v)::numeric),'m2_max',max(v),'ratio',round(max(v)/nullif(min(v),0),2),'rent26_distinct',count(distinct monthly_rent) filter(where area_sqm between 26 and 27.99),'rows26',count(*) filter(where area_sqm between 26 and 27.99)) o from h group by g)q),'가군26_top',(select json_agg(o) from(select json_build_object('rent',monthly_rent,'rows',count(*),'anns',count(distinct announcement_id)) o from h where g='가군' and area_sqm between 26 and 27.99 group by monthly_rent order by count(*) desc,monthly_rent limit 6)q),'나군_sido',(select json_agg(o) from(select json_build_object('sido',sido,'anns',count(distinct announcement_id),'med',round(percentile_cont(0.5)within group(order by v)::numeric)) o from h where g='나군' group by sido order by percentile_cont(0.5)within group(order by v) desc)q),'나군_max_ex',(select json_agg(i) from(select announcement_id||' '||v i from h where g='나군' order by v desc limit 3)q),'혼합_ex',(select json_agg(i) from(select distinct announcement_id||' '||v i from h where g='혼합' order by 1 desc limit 3)q))j;
